<script lang="ts">
	import {
		PROJECT_TYPES,
		PROJECT_TYPE_LABELS,
		type ProjectType
	} from '$shared/domain/record-states';
	import { Input, Select } from '$shared/presentation/ui';

	/**
	 * Step 3 — the project's own identity. Only the caption and type are
	 * editable here: the reference is generated by the workspace, and status
	 * starts as Active (Part 4 §1).
	 */
	interface Props {
		caption: string;
		projectType: ProjectType;
		captionError?: string | null;
		typeError?: string | null;
		oncaption: (value: string) => void;
		ontype: (value: ProjectType) => void;
	}

	let {
		caption,
		projectType,
		captionError = null,
		typeError = null,
		oncaption,
		ontype
	}: Props = $props();

	const typeOptions = PROJECT_TYPES.map((type) => ({
		value: type,
		label: PROJECT_TYPE_LABELS[type]
	}));

	function handleType(event: Event): void {
		const value = (event.currentTarget as HTMLSelectElement).value;
		if ((PROJECT_TYPES as readonly string[]).includes(value)) {
			ontype(value as ProjectType);
		}
	}
</script>

<div class="flex flex-col gap-6">
	<Input
		label="Project caption"
		required
		value={caption}
		placeholder="e.g. Shaker kitchen, ground floor"
		error={captionError ?? undefined}
		hint="Use the name the customer and the team will recognise."
		maxlength={200}
		oninput={(event) => oncaption((event.currentTarget as HTMLInputElement).value)}
	/>

	<Select
		label="Project type"
		required
		value={projectType}
		options={typeOptions}
		error={typeError ?? undefined}
		hint="Type drives which stages later phases apply to this project."
		onchange={handleType}
	/>

	<div class="rounded-md border border-hairline bg-canvas-grouped p-4">
		<p class="text-callout text-ink">The project starts as Active.</p>
		<p class="text-footnote text-ink-secondary">
			The workspace assigns a reference when the project is created. Status changes happen from the
			project hub.
		</p>
	</div>
</div>
